// Generate prompt for AI to create diverse topics
const categories = ['nasa-news', 'space-facts', 'satellite-tutorials', 'astronomy-lessons'];
const topicCategories = ['nasa', 'newton', 'quantum-physics', 'astrophysics', 'orbital-mechanics'];

const category = categories[Math.floor(Math.random() * categories.length)];
const topicCategory = topicCategories[Math.floor(Math.random() * topicCategories.length)];

return {
  json: {
    blogCategory: category,
    topicCategory: topicCategory,
    prompt: `Generate 5 unique blog post topics about ${topicCategory} for an educational space website. Topics should be:
- Educational and informative
- Related to NASA, Newton's laws, quantum physics, astrophysics, or orbital mechanics
- Suitable for students, scientists, and PhD researchers
- Include SEO-friendly titles
- Include brief descriptions

Format as JSON array with: title, excerpt, content outline, keywords`
  }
};

// Parse AI response and create blog post
const aiResponse = $input.item.json.choices[0].message.content;
let topics;

try {
  // Try to parse JSON
  topics = JSON.parse(aiResponse);
} catch (e) {
  // If not JSON, extract topics manually
  topics = [{ title: 'AI Generated Topic', excerpt: 'Generated by AI', content: aiResponse }];
}

// Select first topic
const topic = Array.isArray(topics) ? topics[0] : topics;
const today = new Date().toISOString().split('T')[0];
const slug = (topic.title || 'ai-generated-topic').toLowerCase().replace(/[^a-z0-9]+/g, '-');

return {
  json: {
    slug,
    title: topic.title || 'AI Generated Space Topic',
    excerpt: topic.excerpt || topic.description || 'Learn about space science and orbital mechanics.',
    content: topic.content || topic.contentOutline || `# ${topic.title}\n\n${topic.excerpt}\n\nLearn more with our [simulator](/simulator) and [formulas](/formulas-library).`,
    category: $('Generate AI Prompt').item.json.blogCategory,
    date: today,
    tags: topic.keywords ? topic.keywords.split(',').map(k => k.trim()) : ['space', 'orbital mechanics'],
    seoKeywords: topic.keywords || 'space, orbital mechanics, NASA'
  }
};

// Generate AstroBot knowledge entry from AI response
const aiResponse = $('OpenAI Generate Topics').item.json.choices[0].message.content;
let topics;

try {
  topics = JSON.parse(aiResponse);
} catch (e) {
  topics = [{ title: 'Topic', keywords: ['space'], answer: 'Learn about space science.' }];
}

const topic = Array.isArray(topics) ? topics[0] : topics;
const keywords = topic.keywords ? (Array.isArray(topic.keywords) ? topic.keywords : topic.keywords.split(',').map(k => k.trim())) : [topic.title.toLowerCase()];

return {
  json: {
    keywords: keywords,
    answer: `${topic.title || 'Space Topic'}: ${topic.excerpt || topic.description || 'Learn about this fascinating space topic.'} Learn more at /blog and /research.`,
    category: $('Generate AI Prompt').item.json.topicCategory
  }
};
